"""Markdown report renderer: the default human-readable format."""

from __future__ import annotations

from pathlib import Path

from inspectra.models import Finding, ScanResult, Severity

SEVERITY_ORDER = [Severity.HIGH, Severity.MEDIUM, Severity.LOW, Severity.INFO]

FOOTER = (
    "_This report was generated by Inspectra, a passive security assessment "
    "tool. Inspectra never exploits: it observes, assesses, explains and "
    "reports. Only scan systems you own or are authorized to test._"
)


def render(result: ScanResult) -> str:
    """Render a :class:`ScanResult` as Markdown."""
    lines = [
        "# Inspectra Security Assessment Report",
        "",
        f"**Target:** `{result.target.input}`",
        f"**Date:** {result.metadata.started_at:%Y-%m-%d %H:%M UTC}",
        f"**Tool:** {result.metadata.tool} {result.metadata.version}",
        f"**Duration:** {result.metadata.duration_seconds:.1f}s",
        "",
        _posture_line(result),
        "",
        "## Summary",
        "",
        "| Severity | Count |",
        "|----------|-------|",
    ]
    for severity in SEVERITY_ORDER:
        lines.append(f"| {severity.value.capitalize()} | {result.count_by_severity(severity)} |")
    lines.append(f"| **Total** | **{result.total_findings}** |")
    lines.append("")

    if not result.findings:
        lines.append("No findings were recorded during this scan.")
        lines.append("")
    else:
        lines.append("## Findings")
        lines.append("")
        for finding in _ordered(result):
            lines.extend(_finding_section(finding))

    lines.extend(["---", "", FOOTER, ""])
    return "\n".join(lines)


def _posture_line(result: ScanResult) -> str:
    if result.posture_score is None:
        return "## Posture Score: not scored"
    return f"## Posture Score: {result.posture_score:.1f} / 100 ({result.grade})"


def _ordered(result: ScanResult) -> list[Finding]:
    return sorted(
        result.findings,
        key=lambda finding: (SEVERITY_ORDER.index(finding.severity), finding.rule_id),
    )


def _finding_section(finding: Finding) -> list[str]:
    section = [
        f"### [{finding.severity.value.upper()}] {finding.rule_id} — {finding.title}",
        "",
        f"- **Category:** {finding.category}",
        f"- **Confidence:** {finding.confidence.value.capitalize()}",
        f"- **What was observed:** {finding.description}",
        f"- **Why it matters:** {finding.why_it_matters}",
        f"- **Recommendation:** {finding.recommendation}",
    ]
    if finding.evidence:
        section.append("- **Evidence:**")
        section.extend(f"  - `{line}`" for line in finding.evidence)
    section.append("")
    return section


def write(result: ScanResult, path: Path) -> None:
    """Write the Markdown report to ``path``."""
    path.write_text(render(result), encoding="utf-8")
